import json,numpy as np
from scipy.spatial.transform import Rotation
from PIL import Image,ImageDraw
meta=json.load(open('/app/output/initial/meta.json'))
def cloud(cam, folder='initial'):
 d=np.load('/app/output/'+folder+'/depth_'+cam+'.npy').astype(float)
 cal=meta['cameras'][cam]; K=np.array(cal['intrinsic_cv']); T=np.array(cal['cam2world_gl'])
 y,x=np.indices(d.shape)
 p=np.stack([(x-K[0,2])*d/K[0,0],-(y-K[1,2])*d/K[1,1],-d],axis=-1)
 return p@T[:3,:3].T+T[:3,3]
def project(cam,p):
 cal=meta['cameras'][cam]; K=np.array(cal['intrinsic_cv']); T=np.array(cal['cam2world_gl'])
 v=(np.array(p)-T[:3,3])@T[:3,:3]; v=v*np.array([1,-1,-1]); return (v@K.T)[...,:2]/v[...,2:3]
if __name__=='__main__':
 for cam in meta['cameras']:
