from vision import *
from scipy.spatial import cKDTree
from scipy.optimize import least_squares

def extract(folder):
 ar=np.load('/app/output/'+folder+'.npz');greens=[];blacks=[]
 for cam in meta['cameras']:
  p=cloud(cam,folder).reshape(-1,3);a=ar[cam].reshape(-1,3).astype(float)
  box=(p[:,0]>-.22)&(p[:,0]<.25)&(p[:,1]>-.12)&(p[:,1]<.25)&(p[:,2]>.541)&(p[:,2]<.73)
  green=(a[:,1]>a[:,0]*1.7+30)&(a[:,1]>a[:,2]*1.5+20)&box
  black=(a.max(-1)-a.min(-1)<20)&(a.mean(-1)<150)&box
  greens.append(p[green]);blacks.append(p[black])
 return np.concatenate(greens),np.concatenate(blacks)
def fit(a,b,init=None):
 if init is None: R=np.eye(3);t=np.array([0,.03,-.09])
 else:R,t=init
 tree=cKDTree(b)
 for k in range(100):
  x=a@R.T+t;d,idx=tree.query(x);keep=d<min(.05,np.quantile(d,.85));aa=x[keep];bb=b[idx[keep]];ac=aa.mean(0);bc=bb.mean(0)
  u,s,vt=np.linalg.svd((aa-ac).T@(bb-bc));rr=vt.T@u.T
  if np.linalg.det(rr)<0:vt[-1]*=-1;rr=vt.T@u.T
  tt=bc-rr@ac;R=rr@R;t=rr@t+tt
 return R,t,np.mean(np.minimum(d,.03)**2)**.5
if __name__=='__main__':
 import sys
 folder=sys.argv[1];g,b=extract(folder);print('points',len(g),len(b));best=None
 for yaw in [-.5,-.25,0,.25,.5]:
  R0=Rotation.from_euler('z',yaw).as_matrix();t0=b.mean(0)-R0@g.mean(0);R,t,e=fit(g,b,(R0,t0))
  print('fit',yaw,e,Rotation.from_matrix(R).as_euler('xyz'),t)
  if best is None or e<best[0]:best=(e,R,t)
 e,R,t=best;goal=np.array(meta['task']['goal']);pg=goal[:3];Rg=Rotation.from_quat(goal[3:]).as_matrix();p=R@pg+t;Rt=R@Rg
 print('POSE',p,Rotation.from_matrix(Rt).as_quat());np.savez('/app/output/tool_est.npz',p=p,R=Rt)
 # pointcloud overlays top x-y and front x-z
 im=Image.new('RGB',(1200,650),'#c0d0e0');dr=ImageDraw.Draw(im)
 for ps,col in [(b,'black'),(g@R.T+t,'red')]:
  for a in ps:
   u=int((a[0]+.25)*1100);v=int((.75-a[2])*2300);dr.ellipse((u-1,v-1,u+1,v+1),fill=col)
   u+=600;v=int((a[1]+.15)*1400);dr.ellipse((u-1,v-1,u+1,v+1),fill=col)
 im.save('/app/output/fit.jpg')
